// === Tab: mySketch ===
// Versión simplificada de tu código Splash con círculos grandes

let splashes = [];

function setup() {
  createCanvas(windowWidth, windowHeight);
  noStroke();
  for (let i = 0; i < 5; i++) {
    splashes.push(new Splash(random(width), random(height), random(100, 300)));
  }
}

function draw() {
  background(255, 10); // fondo que se desvanece suavemente
  for (let s of splashes) {
    s.paint();
  }
}

class Splash {
  constructor(x, y, poolR) {
    this.x = x;
    this.y = y;
    this.poolR = poolR;
    this.c = color(random(255), random(255), random(255), 100);
  }

  paint() {
    fill(this.c);
    let numCircles = 10;
    for (let i = 0; i < numCircles; i++) {
      let r = this.poolR * random(0.2, 1);
      ellipse(this.x + random(-r / 2, r / 2), this.y + random(-r / 2, r / 2), r);
    }
  }
}

// Si presionás "S", cambia los colores
function keyPressed() {
  if (key === 'S' || key === 's') {
    for (let s of splashes) {
      s.c = color(random(255), random(255), random(255), 100);
    }
  }
}

